import re

from click import prompt


def _normalized_doc(func) -> str:
    return " ".join((func.__doc__ or "").split())


def test_prompt_8_5_0_changelog_says_or_default():
    doc = _normalized_doc(prompt)
    expected = (
        "Generically typed: the return type is narrowed by "
        "``type``, ``value_proc``, or ``default`` instead of being "
        "``Any``."
    )
    assert expected in doc

import pytest

from pydantic import BaseModel


def _normalized_doc(obj) -> str:
    # Collapse all whitespace (including the docstring's line wrap) to single spaces.
    return " ".join((obj.__doc__ or "").split())


def test_basemodel_docstring_describes_origin_and_args_with_and():
    doc = _normalized_doc(BaseModel)
    expected = (
        "The `origin` and `args` items map to the "
        "[`__origin__`][genericalias.__origin__] and "
        "[`__args__`][genericalias.__args__] attributes of "
        "[generic aliases][types-genericalias]"
    )
    assert expected in doc, (
        "BaseModel.__doc__ should join __origin__ and __args__ with 'and', "
        "not 'or'"
    )


def test_basemodel_docstring_does_not_use_or_for_args_attributes():
    doc = _normalized_doc(BaseModel)
    assert "[`__origin__`][genericalias.__origin__] or [`__args__`][genericalias.__args__]" not in doc

import structlog.dev
from structlog.dev import ConsoleRenderer


def _normalized_doc(obj) -> str:
    doc = obj.__doc__ or ""
    return " ".join(doc.split())


def test_exception_formatter_docstring_says_or_implement_your_own():
    doc = _normalized_doc(ConsoleRenderer)
    assert "`rich_traceback`, or implement your own." in doc


def test_exception_formatter_docstring_does_not_say_and_implement_your_own():
    doc = _normalized_doc(ConsoleRenderer)
    assert "`rich_traceback`, and implement your own." not in doc

import starlette


def test_package_version_is_1_7_0():
    assert starlette.__version__ == "1.7.0"

