import click


def _normalized_doc(obj) -> str:
    return " ".join((obj.__doc__ or "").split())


def test_custom_version_option_doc_says_or_git_metadata():
    doc = _normalized_doc(click.custom_version_option)
    assert "Python version, or git metadata." in doc


def test_custom_version_option_doc_does_not_say_and_git_metadata():
    doc = _normalized_doc(click.custom_version_option)
    assert "Python version, and git metadata." not in doc

import sys
import typing as t

import pytest

from click.testing import CaptureMode


@pytest.mark.skipif(sys.platform == "win32", reason="fd capture is not offered on Windows")
def test_capture_mode_offers_fd_on_posix() -> None:
    assert "fd" in t.get_args(CaptureMode)


@pytest.mark.skipif(sys.platform == "win32", reason="fd capture is not offered on Windows")
def test_capture_mode_exact_values_on_posix() -> None:
    assert t.get_args(CaptureMode) == ("sys", "fd")

import more_itertools
from more_itertools import duplicates_everseen


def _normalized_doc(func):
    return " ".join(func.__doc__.split())


def test_duplicates_everseen_docstring_recommends_same_key_for_unique_everseen():
    doc = _normalized_doc(duplicates_everseen)
    assert "pass the return value of this function into :func:`unique_everseen` with the same ``key``." in doc


def test_duplicates_everseen_docstring_does_not_recommend_no_key_for_unique_everseen():
    doc = _normalized_doc(duplicates_everseen)
    assert "into :func:`unique_everseen` with no ``key``." not in doc


def test_duplicates_everseen_is_exported_and_callable():
    assert more_itertools.duplicates_everseen is duplicates_everseen
    assert list(duplicates_everseen("aba")) == ["a"]

import re
from typing import Annotated, Literal, Union

import pytest

from pydantic import BaseModel, BeforeValidator, Field, PlainValidator, PydanticUserError, WrapValidator


@pytest.mark.parametrize(
    ('validator', 'mode'),
    [
        (BeforeValidator(lambda v: v), 'before'),
        (WrapValidator(lambda v, handler: handler(v)), 'wrap'),
        (PlainValidator(lambda v: v), 'plain'),
    ],
)
def test_discriminator_validator_error_reports_mode(validator, mode):
    class A(BaseModel):
        kind: Annotated[Literal['a'], validator]

    class B(BaseModel):
        kind: Literal['b']

    with pytest.raises(PydanticUserError, match=re.escape(f"Cannot use a mode='{mode}' validator")) as exc_info:

        class Model(BaseModel):
            x: Union[A, B] = Field(discriminator='kind')

    assert exc_info.value.code == 'discriminator-validator'

import click
from click.testing import CliRunner


def test_option_ignores_auto_envvar_when_allow_from_autoenv_is_false():
    @click.command()
    @click.option("--foo", allow_from_autoenv=False)
    def cli(foo):
        click.echo(repr(foo))

    runner = CliRunner()
    result = runner.invoke(
        cli,
        [],
        auto_envvar_prefix="APP",
        env={"APP_FOO": "bar"},
    )

    assert result.exit_code == 0
    assert result.output == "None\n"

