import starlette


def test_package_version_is_0_46_2():
    assert starlette.__version__ == "0.46.2"

import starlette


def test_package_version_is_0_47_3():
    assert starlette.__version__ == "0.47.3"

import re

from more_itertools import duplicates_everseen


def _normalized_doc(func):
    # Collapse all whitespace runs so the check is independent of line wrapping.
    return re.sub(r"\s+", " ", func.__doc__ or "")


def test_duplicates_everseen_docstring_uses_or_for_unix_shell_reference():
    doc = _normalized_doc(duplicates_everseen)
    assert "in the Unix shell or ``Itertools::duplicates``" in doc


def test_duplicates_everseen_docstring_does_not_use_and_for_unix_shell_reference():
    doc = _normalized_doc(duplicates_everseen)
    assert "in the Unix shell and ``Itertools::duplicates``" not in doc

