import inspect
import typing

from fastapi import FastAPI


def _check_dir_doc() -> str | None:
    """Find the Doc text attached to the `check_dir` parameter of a public FastAPI method."""
    for _, member in inspect.getmembers(FastAPI):
        if not callable(member):
            continue
        try:
            sig = inspect.signature(member)
        except (TypeError, ValueError):
            continue
        if "check_dir" not in sig.parameters:
            continue
        try:
            hints = typing.get_type_hints(member, include_extras=True)
        except Exception:
            continue
        annotation = hints.get("check_dir")
        for meta in getattr(annotation, "__metadata__", ()):
            doc = getattr(meta, "documentation", None)
            if doc:
                return doc
    return None


def test_check_dir_doc_says_if_it_is_not_already_set():
    doc = _check_dir_doc()
    assert doc is not None, "check_dir parameter documentation not found on FastAPI"

    normalized = " ".join(doc.split())

    assert "if it is not already set" in normalized
    assert "if not it is not already set" not in normalized

