import pytest

from pydantic._internal._model_construction import complete_model_class


def _normalized_doc(func) -> str:
    # Collapse all whitespace so the check is independent of line wrapping/indentation.
    return " ".join((func.__doc__ or "").split())


def test_is_force_rebuild_doc_says_if_true():
    doc = _normalized_doc(complete_model_class)
    assert "is_force_rebuild: Whether the model is being force-rebuilt (if True, pre-built serializers and" in doc


def test_is_force_rebuild_doc_does_not_say_if_not_true():
    doc = _normalized_doc(complete_model_class)
    assert "if not True" not in doc

import pytest

from more_itertools import tail


def test_tail_zero_returns_empty_sized_iterable():
    assert list(tail(0, 'ABCDEFG')) == []


def test_tail_zero_returns_empty_unsized_iterable():
    assert list(tail(0, iter('ABCDEFG'))) == []


def test_tail_negative_raises_value_error():
    with pytest.raises(ValueError):
        tail(-1, 'ABC')

import starlette


def test_version_is_0_47_0():
    assert starlette.__version__ == "0.47.0"

import starlette


def test_package_version_is_pinned():
    assert starlette.__version__ == "1.3.0"

from structlog.dev import RichTracebackFormatter


def test_rich_traceback_formatter_word_wrap_defaults_to_true():
    assert RichTracebackFormatter().word_wrap is True

import inspect

import pydantic.config as config_module

SOURCE = inspect.getsource(config_module)


def _ser_json_temporal_docstring() -> str:
    start = SOURCE.index("ser_json_temporal: Literal")
    end = SOURCE.index("val_temporal_unit: Literal", start)
    return SOURCE[start:end]


def test_ser_json_temporal_doc_says_it_takes_precedence():
    assert "It takes precedence over `ser_json_timedelta`." in _ser_json_temporal_docstring()


def test_ser_json_temporal_doc_does_not_say_it_is_overridden():
    assert "It is overridden by `ser_json_timedelta` when both are set." not in _ser_json_temporal_docstring()

from more_itertools import sum_of_squares


def test_sum_of_squares_accepts_one_shot_iterator():
    # A generator can only be consumed once. The sum of squares must still
    # be computed over each element, not over interleaved pairs.
    assert sum_of_squares(iter([10, 20, 30])) == 1400


def test_sum_of_squares_generator_matches_list():
    values = [1, 2, 3, 4]
    assert sum_of_squares(x for x in values) == sum_of_squares(values) == 30


def test_sum_of_squares_single_element_generator():
    assert sum_of_squares(x for x in [7]) == 49

import click
from click.shell_completion import get_completion_class


def _powershell_script() -> str:
    cls = get_completion_class("powershell")
    cli = click.Command("tool")
    return cls(cli, {}, "tool", "_TOOL_COMPLETE").source()


def test_powershell_script_uses_count_minus_one_for_partial_word():
    script = _powershell_script()
    assert "$env:COMP_CWORD = $commandAst.CommandElements.Count - 1" in script


def test_powershell_script_has_no_count_minus_zero_offset():
    script = _powershell_script()
    assert "CommandElements.Count - 0" not in script

import sys

import pydantic
import pytest

from fastapi._compat import shared


@pytest.fixture
def pydantic_v1_unavailable(monkeypatch):
    # Make `from pydantic import v1` raise ImportError, which is the
    # branch guarded by `# pragma: no cover` in the original code.
    monkeypatch.delattr(pydantic, "v1", raising=False)
    monkeypatch.setitem(sys.modules, "pydantic.v1", None)


def test_model_instance_check_false_when_pydantic_v1_missing(
    pydantic_v1_unavailable,
):
    assert shared.is_pydantic_v1_model_instance(object()) is False


def test_model_class_check_false_when_pydantic_v1_missing(
    pydantic_v1_unavailable,
):
    assert shared.is_pydantic_v1_model_class(int) is False


def test_annotation_check_false_when_pydantic_v1_missing(
    pydantic_v1_unavailable,
):
    assert shared.annotation_is_pydantic_v1(int) is False

from more_itertools import running_median


def _normalized_doc():
    return " ".join(running_median.__doc__.split())


def test_numeric_types_line_uses_and_not_or():
    doc = _normalized_doc()
    assert (
        "Supports numeric types such as int, float, Decimal, and Fraction,"
        in doc
    )


def test_numeric_types_line_does_not_use_or():
    doc = _normalized_doc()
    assert (
        "Supports numeric types such as int, float, Decimal, or Fraction,"
        not in doc
    )

