def test_package_version_is_0_52_1():
    assert starlette.__version__ == "0.52.1"

import starlette


def test_package_version_is_pinned():
    assert starlette.__version__ == "0.49.1"

from types import SimpleNamespace

import pytest

import pdm_build


def _make_context(packages: dict, sync_dependencies=None) -> SimpleNamespace:
    slim = {
        "sync-dependencies": sync_dependencies or [],
        "packages": packages,
    }
    data = {"tool": {"tiangolo": {"_internal-slim-build": slim}}}
    config = SimpleNamespace(
        metadata={"version": "1.2.3", "dependencies": []},
        data=data,
        build_config={},
    )
    return SimpleNamespace(config=config)


def test_missing_package_config_is_a_no_op(monkeypatch: pytest.MonkeyPatch) -> None:
    # Package name absent from configs: the hook must return quietly and
    # leave metadata untouched.
    monkeypatch.setattr(pdm_build, "TIANGOLO_BUILD_PACKAGE", "typer")
    context = _make_context(packages={"other": {"project": {"name": "other"}}})
    before = dict(context.config.metadata)

    pdm_build.pdm_build_initialize(context)

    assert context.config.metadata == before


def test_present_package_config_is_applied(monkeypatch: pytest.MonkeyPatch) -> None:
    # Package name present in configs: its [project] overrides must be applied.
    monkeypatch.setattr(pdm_build, "TIANGOLO_BUILD_PACKAGE", "typer")
    context = _make_context(
        packages={"typer": {"project": {"name": "typer-slim"}}}
    )

    pdm_build.pdm_build_initialize(context)

    assert context.config.metadata["name"] == "typer-slim"

import pytest

from more_itertools import random_ordered_combs_with_replacement


def test_empty_input_with_r_zero_yields_single_empty_tuple():
    # combinations_with_replacement([], 0) has exactly one element: ().
    result = list(random_ordered_combs_with_replacement([], 0))
    assert result == [()]


def test_empty_input_with_positive_r_yields_nothing():
    # combinations_with_replacement([], 2) has no elements.
    result = list(random_ordered_combs_with_replacement([], 2))
    assert result == []


@pytest.mark.parametrize("r", [1, 2, 3])
def test_empty_input_with_positive_r_is_empty_for_all_r(r):
    assert list(random_ordered_combs_with_replacement([], r)) == []

from typing import Sequence

from fastapi import FastAPI, Query
from fastapi.testclient import TestClient


def test_sequence_query_param_accepts_repeated_values() -> None:
    app = FastAPI()

    @app.get("/")
    def read(q: Sequence[int] = Query()) -> dict[str, list[int]]:
        return {"q": list(q)}

    client = TestClient(app)
    response = client.get("/", params=[("q", "1"), ("q", "2")])

    assert response.status_code == 200
    assert response.json() == {"q": [1, 2]}

import starlette


def test_version_is_0_50_0():
    assert starlette.__version__ == "0.50.0"

import re

import pydantic.dataclasses as pd_dataclasses


def _normalized_doc(obj) -> str:
    return re.sub(r"\s+", " ", obj.__doc__ or "")


def test_unsafe_hash_docstring_describes_hash_inclusion():
    doc = _normalized_doc(pd_dataclasses.dataclass)
    assert (
        "unsafe_hash: Determines if a `__hash__()` method should be included in the class"
        in doc
    )


def test_unsafe_hash_true_generates_hash(tmp_path):
    @pd_dataclasses.dataclass(unsafe_hash=True)
    class Point:
        x: int

    assert Point.__hash__ is not None
    assert hash(Point(1)) == hash(Point(1))

