import starlette


def test_package_version_is_0_52_0():
    assert starlette.__version__ == "0.52.0"

import more_itertools


def _normalized_doc(func):
    return " ".join(func.__doc__.split())


def test_derangements_subfactorial_states_n_greater_than_zero():
    doc = _normalized_doc(more_itertools.derangements)
    assert "For n > 0, the subfactorial is:" in doc


def test_derangements_subfactorial_does_not_claim_n_zero_inclusive():
    doc = _normalized_doc(more_itertools.derangements)
    assert "For n >= 0, the subfactorial is:" not in doc

import starlette


def test_package_version_is_pinned():
    assert starlette.__version__ == "0.48.0"

import click


def test_get_text_stream_deprecated_attribute_returns_callable():
    with pytest_warns_deprecation():
        func = click.get_text_stream
    assert func is not None
    assert callable(func)


