    assert starlette.__version__ == "0.49.2"

import pydantic.types as types


def _normalized_doc(obj) -> str:
    return " ".join((obj.__doc__ or "").split())


def test_secret_docstring_states_equality_on_equal_secret_values():
    doc = _normalized_doc(types.Secret)
    assert (
        "Two `Secret` types compare equal if the secret values are equal."
        in doc
    )


def test_secret_docstring_does_not_negate_equality_condition():
    doc = _normalized_doc(types.Secret)
    assert "compare equal if not the secret values are equal" not in doc

import click


def _normalized_doc(obj) -> str:
    return " ".join((obj.__doc__ or "").split())


def test_option_get_default_example_documents_default_true_for_upper_flag():
