    expected = (
        '``flag_value="upper"`` and ``default=True``, the default resolves'
    )
    assert expected in doc

import re

from more_itertools import convolve


def _normalized_doc(func):
    return re.sub(r"\s+", " ", func.__doc__ or "")


def test_convolve_docstring_describes_moving_average_as_blurring():
    doc = _normalized_doc(convolve)
    assert "For image data, this blurs the image and reduces noise." in doc


def test_convolve_docstring_does_not_claim_sharpening():
    doc = _normalized_doc(convolve)
    assert "sharpens the image and amplifies noise" not in doc

from fastapi.security.utils import get_authorization_scheme_param


def test_splits_scheme_and_param():
    assert get_authorization_scheme_param("Bearer abc123") == ("Bearer", "abc123")


def test_strips_surrounding_whitespace_from_param():
    assert get_authorization_scheme_param("Bearer   abc123  ") == ("Bearer", "abc123")


def test_scheme_without_param_returns_empty_param():
    assert get_authorization_scheme_param("Bearer") == ("Bearer", "")


def test_none_input_returns_empty_pair():
    assert get_authorization_scheme_param(None) == ("", "")


def test_empty_string_returns_empty_pair():
    assert get_authorization_scheme_param("") == ("", "")


def test_returns_a_two_element_tuple_of_strings():
    result = get_authorization_scheme_param("Basic dXNlcjpwYXNz")
    assert isinstance(result, tuple)
    assert len(result) == 2
    assert all(isinstance(part, str) for part in result)

import pytest

from fastapi.security.utils import get_authorization_scheme_param


@pytest.mark.parametrize(
    ("header", "expected"),
    [
        ("Bearer abc123", ("Bearer", "abc123")),
        ("Basic dXNlcjpwYXNz", ("Basic", "dXNlcjpwYXNz")),
        ("Bearer   spaced-token  ", ("Bearer", "spaced-token")),
        ("Bearer x", ("Bearer", "x")),
    ],
)
def test_returns_scheme_and_full_credentials(header, expected):
    assert get_authorization_scheme_param(header) == expected


def test_credentials_are_not_truncated():
    _, credentials = get_authorization_scheme_param("Bearer token123")
    assert credentials == "token123"


def test_missing_credentials_returns_empty_string():
    assert get_authorization_scheme_param("Bearer") == ("Bearer", "")


@pytest.mark.parametrize("header", [None, ""])
def test_empty_or_none_header_returns_empty_pair(header):
    assert get_authorization_scheme_param(header) == ("", "")

