def test_version_is_1_2_1():
    assert starlette.__version__ == "1.2.1"

import pytest

from structlog import dev


class _FakeColorama:
    def __init__(self):
        self.calls = []

    def init(self, **kwargs):
        self.calls.append(("init", kwargs))

    def deinit(self, **kwargs):
        self.calls.append(("deinit", kwargs))


def test_force_colors_on_windows_reinitializes_colorama_without_stripping(
    monkeypatch,
):
    fake = _FakeColorama()
    monkeypatch.setattr(dev, "_IS_WINDOWS", True)
    monkeypatch.setattr(dev, "colorama", fake)

    dev.ConsoleRenderer.get_default_column_styles(
        colors=True, force_colors=True
    )

    assert fake.calls == [("deinit", {}), ("init", {"strip": False})]

import io
import sys

import pytest

from structlog import dev


class _FakeBetterExceptions:
    """Stub so the test does not depend on the optional better-exceptions package."""

    @staticmethod
    def format_exception(*exc_info):
        return ["formatted-traceback\n"]


def _current_exc_info():
    try:
        raise ValueError("boom")
    except ValueError:
        return sys.exc_info()


def test_better_traceback_emits_deprecation_warning(monkeypatch):
    monkeypatch.setattr(dev, "better_exceptions", _FakeBetterExceptions())
    sio = io.StringIO()

    with pytest.warns(DeprecationWarning):
        dev.better_traceback(sio, _current_exc_info())

    assert "formatted-traceback" in sio.getvalue()

import inspect

from starlette.middleware.opentelemetry import OpenTelemetryMiddleware


def _normalized_doc() -> str:
    doc = inspect.getdoc(OpenTelemetryMiddleware)
    assert doc is not None, "OpenTelemetryMiddleware must have a docstring"
    return " ".join(doc.split())


def test_docstring_declares_middleware_experimental() -> None:
    assert "This middleware is experimental." in _normalized_doc()


def test_docstring_does_not_declare_middleware_stable() -> None:
    assert "This middleware is stable." not in _normalized_doc()

from starlette._utils import ParsedHost


def test_port_65535_is_valid() -> None:
    # The highest valid TCP port must be accepted.
    assert ParsedHost(host="example.com", port="65535").is_valid_port is True


def test_port_65536_is_invalid() -> None:
    assert ParsedHost(host="example.com", port="65536").is_valid_port is False


def test_port_zero_is_valid() -> None:
    assert ParsedHost(host="example.com", port="0").is_valid_port is True


def test_missing_port_is_valid() -> None:
    assert ParsedHost(host="example.com", port=None).is_valid_port is True
